import org.springframework.test.context.DynamicPropertyRegistry;

/**
 * The backend's configuration as the acceptance tests set it: the environment settings of {@code
 * docs/02_specification.md} section 9, plus the standard Spring datasource properties.
 */
public final class Settings {

  public static final String ORGANIZER_USERNAME = "organizer";
  public static final String ORGANIZER_PASSWORD = "acceptance-organizer-pw-2026";
  public static final List<String> ORGANIZER_EMAILS =
      List.of("organizer-one@example.org", "organizer-two@example.org");
  public static final String CONFERENCE_NAME = "Acceptance Conference 2026";
  public static final String CAPTCHA_PASS = "test-pass";
  public static final String CONFERENCE_CONFIG = "classpath:acceptance/conference.json";

  private Settings() {}

  /** The settings every acceptance context starts from. */
  public static Map<String, String> defaults(Path jsonCopyDir) {
    Map<String, String> values = new LinkedHashMap<>();
    values.put("spring.datasource.url", Containers.POSTGRES.getJdbcUrl());
    values.put("spring.datasource.username", Containers.POSTGRES.getUsername());
    values.put("spring.datasource.password", Containers.POSTGRES.getPassword());
    values.put("APP_ENVIRONMENT", "test");
    values.put("SMTP_HOST", Containers.MAILPIT.getHost());
    values.put(
        "SMTP_PORT", String.valueOf(Containers.MAILPIT.getMappedPort(Containers.SMTP_PORT)));
    values.put("SMTP_TLS", "false");
    values.put("MAIL_FROM", "registration@acceptance.example.org");
    values.put("CONFERENCE_NAME", CONFERENCE_NAME);
    values.put("CONFERENCE_CONFIG", CONFERENCE_CONFIG);
    values.put("JSON_COPY_DIR", jsonCopyDir.toString());
    values.put("CAPTCHA_TEST_MODE", "true");
    values.put("RECAPTCHA_SITE_KEY", "acceptance-site-key");
    values.put("RECAPTCHA_SECRET_KEY", "acceptance-secret-key");
    values.put("ORGANIZER_USERNAME", ORGANIZER_USERNAME);
    values.put("ORGANIZER_PASSWORD", ORGANIZER_PASSWORD);
    values.put("ORGANIZER_EMAILS", String.join(",", ORGANIZER_EMAILS));
    values.put("ORGANIZER_HTTPS_ONLY", "true");
    values.put("RATE_LIMIT_PER_MINUTE", "100000");
    return values;
  }

  public static void register(DynamicPropertyRegistry registry, Map<String, String> values) {
    values.forEach((name, value) -> registry.add(name, () -> value));
  }

  /** The same settings as command-line arguments, for starting the backend directly. */
  public static String[] asArguments(Map<String, String> values) {
    List<String> arguments = new ArrayList<>();
    values.forEach((name, value) -> arguments.add("--" + name + "=" + value));
    return arguments.toArray(String[]::new);
  }

  public static Path newDirectory(String prefix) {
    try {
      return Files.createTempDirectory(prefix);
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }
}

package si.konferenca.registration.acceptance.support;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URI;
import java.net.URLEncoder;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/** Calls the backend over real HTTP, as a browser or organizer client would. */
public final class HttpApi {

  public static final JsonMapper JSON = JsonMapper.builder().build();

  private final HttpClient client =
      HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
  private final String baseUrl;

  public HttpApi(int port) {
    this.baseUrl = "http://127.0.0.1:" + port;
  }

  /** Sends a GET; {@code headers} are name, value pairs. */
  public Response get(String pathAndQuery, String... headers) {
    HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(baseUrl + pathAndQuery)).GET();
    return send(request, headers);
  }

  public Response postJson(String path, Object body, String... headers) {
    HttpRequest.Builder request =
        HttpRequest.newBuilder(URI.create(baseUrl + path))
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofByteArray(JSON.writeValueAsBytes(body)));
    return send(request, headers);
  }

  public Response getAsOrganizer(String pathAndQuery, String... headers) {
    String[] all = new String[headers.length + 2];
    all[0] = "Authorization";
    all[1] = basic(Settings.ORGANIZER_USERNAME, Settings.ORGANIZER_PASSWORD);
    System.arraycopy(headers, 0, all, 2, headers.length);
    return get(pathAndQuery, all);
  }

  public static String basic(String username, String password) {
    String pair = username + ":" + password;
    return "Basic " + Base64.getEncoder().encodeToString(pair.getBytes(StandardCharsets.UTF_8));
  }

  /** Builds {@code ?a=1&b=2} with UTF-8 encoding; an empty map gives an empty string. */
  public static String query(Map<String, String> parameters) {
    if (parameters.isEmpty()) {
      return "";
    }
    return parameters.entrySet().stream()
        .map(e -> encode(e.getKey()) + "=" + encode(e.getValue()))
        .collect(Collectors.joining("&", "?", ""));
  }

  private static String encode(String value) {
    return URLEncoder.encode(value, StandardCharsets.UTF_8);
  }

  private Response send(HttpRequest.Builder request, String... headers) {
    for (int i = 0; i < headers.length; i += 2) {
      request.header(headers[i], headers[i + 1]);
    }
    try {
      HttpResponse<byte[]> response =
          client.send(
              request.timeout(Duration.ofSeconds(60)).build(),
              HttpResponse.BodyHandlers.ofByteArray());
      return new Response(response.statusCode(), response.headers().map(), response.body());
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new IllegalStateException(e);
    }
  }

  /** A received response. */
  public record Response(int status, Map<String, List<String>> headers, byte[] body) {

    public String text() {
      return new String(body, StandardCharsets.UTF_8);
    }

    public JsonNode json() {
      return JSON.readTree(body);
    }

    public String header(String name) {
      return headers.entrySet().stream()
          .filter(e -> e.getKey().equalsIgnoreCase(name))
          .flatMap(e -> e.getValue().stream())
          .findFirst()
          .orElse(null);
    }

    /** The {@code field} of every entry in the error body, or an empty list. */
    public List<String> errorFields() {
      if (body.length == 0) {
        return List.of();
      }
      JsonNode errors;
      try {
        errors = json().path("errors");
      } catch (RuntimeException notJson) {
        return List.of();
      }
      return errors.valueStream().map(e -> e.path("field").asString()).toList();
    }

    @Override
    public String toString() {
      return status + " " + text();
    }
  }
}

package si.konferenca.registration.acceptance.support;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

/** Reads the registration tables of {@code docs/02_contracts/database.md} with plain JDBC. */
public final class Database {

  /** One row of {@code registration}. */
  public record Row(
      UUID id,
      String type,
      String firstName,
      String lastName,
      String email,
      String organization,
      String studyInstitution,
      String studyProgramme,
      String studentId,
      OffsetDateTime registeredAt) {}

  private Connection connect() throws SQLException {
    return DriverManager.getConnection(
        Containers.POSTGRES.getJdbcUrl(),
        Containers.POSTGRES.getUsername(),
        Containers.POSTGRES.getPassword());
  }

  /** Empties the registration tables, if the schema exists yet. */
  public void clear() {
    if (!schemaExists()) {
      return;
    }
    update("TRUNCATE registration_option, registration_consent, registration");
  }

  public boolean schemaExists() {
    return queryOne("SELECT to_regclass('public.registration') IS NOT NULL", Boolean.class);
  }

  public long countRegistrations() {
    if (!schemaExists()) {
      return 0;
    }
    return queryOne("SELECT count(*) FROM registration", Long.class);
  }

  public List<Row> rows() {
    List<Row> rows = new ArrayList<>();
    query(
        "SELECT id, type, first_name, last_name, email, organization, study_institution,"
            + " study_programme, student_id, registered_at FROM registration ORDER BY registered_at",
        rs ->
            rows.add(
                new Row(
                    rs.getObject("id", UUID.class),
                    rs.getString("type"),
                    rs.getString("first_name"),
                    rs.getString("last_name"),
                    rs.getString("email"),
                    rs.getString("organization"),
                    rs.getString("study_institution"),
                    rs.getString("study_programme"),
                    rs.getString("student_id"),
                    rs.getObject("registered_at", OffsetDateTime.class))));
    return rows;
  }

  public Row row(UUID id) {
    return rows().stream()
        .filter(r -> r.id().equals(id))
        .findFirst()
        .orElseThrow(() -> new AssertionError("no registration row " + id));
  }

  public List<String> optionIds(UUID id) {
    List<String> ids = new ArrayList<>();
    query(
        "SELECT option_id FROM registration_option WHERE registration_id = ? ORDER BY option_id",
        rs -> ids.add(rs.getString(1)),
        id);
    return ids;
  }

  /** Consent id to the time it was given. */
  public Map<String, OffsetDateTime> consents(UUID id) {
    Map<String, OffsetDateTime> consents = new LinkedHashMap<>();
    query(
        "SELECT consent_id, given_at FROM registration_consent WHERE registration_id = ?"
            + " ORDER BY consent_id",
        rs -> consents.put(rs.getString(1), rs.getObject(2, OffsetDateTime.class)),
        id);
    return consents;
  }

  private interface RowHandler {
    void handle(ResultSet rs) throws SQLException;
  }

  private void query(String sql, RowHandler handler, Object... parameters) {
    try (Connection connection = connect();
        PreparedStatement statement = connection.prepareStatement(sql)) {
      for (int i = 0; i < parameters.length; i++) {
        statement.setObject(i + 1, parameters[i]);
      }
      try (ResultSet rs = statement.executeQuery()) {
        while (rs.next()) {
          handler.handle(rs);
        }
      }
    } catch (SQLException e) {
      throw new IllegalStateException(e);
    }
  }

  private <T> T queryOne(String sql, Class<T> type) {
    List<T> values = new ArrayList<>();
    query(sql, rs -> values.add(rs.getObject(1, type)));
    return values.getFirst();
  }

  private void update(String sql) {
    try (Connection connection = connect();
        PreparedStatement statement = connection.prepareStatement(sql)) {
      statement.executeUpdate();
    } catch (SQLException e) {
      throw new IllegalStateException(e);
    }
  }
}

package si.konferenca.registration.acceptance.support;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.List;
import tools.jackson.databind.JsonNode;

/** Reads the messages the backend sent, through the Mailpit HTTP API. */
public final class Mailpit {

  private final HttpClient client = HttpClient.newHttpClient();
  private final String baseUrl = Containers.mailpitBaseUrl();

  public void deleteAll() {
    send(HttpRequest.newBuilder(URI.create(baseUrl + "/api/v1/messages")).DELETE());
  }

  /** Summaries of every stored message (fields {@code ID}, {@code To}, {@code Subject}, …). */
  public List<JsonNode> messages() {
    JsonNode list = getJson("/api/v1/messages?limit=1000");
    return list.path("messages").valueStream().toList();
  }

  /** Waits up to ten seconds until at least {@code count} messages are stored. */
  public List<JsonNode> awaitMessages(int count) {
    long deadline = System.nanoTime() + Duration.ofSeconds(10).toNanos();
    List<JsonNode> messages = messages();
    while (messages.size() < count && System.nanoTime() < deadline) {
      pause();
      messages = messages();
    }
    return messages;
  }

  /** The full message: {@code Text}, {@code HTML}, {@code To}, {@code Cc}, {@code Bcc}, … */
  public JsonNode message(String id) {
    return getJson("/api/v1/message/" + id);
  }

  /** Header name to its values, as received. */
  public JsonNode headers(String id) {
    return getJson("/api/v1/message/" + id + "/headers");
  }

  public byte[] part(String id, String partId) {
    return send(
            HttpRequest.newBuilder(URI.create(baseUrl + "/api/v1/message/" + id + "/part/" + partId))
                .GET())
        .body();
  }

  /** Every recipient address (To, Cc, Bcc) of a full message, lower case. */
  public static List<String> recipients(JsonNode message) {
    return List.of("To", "Cc", "Bcc").stream()
        .flatMap(field -> message.path(field).valueStream())
        .map(address -> address.path("Address").asString().toLowerCase())
        .toList();
  }

  private JsonNode getJson(String path) {
    return HttpApi.JSON.readTree(send(HttpRequest.newBuilder(URI.create(baseUrl + path)).GET()).body());
  }

  private HttpResponse<byte[]> send(HttpRequest.Builder request) {
    try {
      return client.send(request.build(), HttpResponse.BodyHandlers.ofByteArray());
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
      throw new IllegalStateException(e);
    }
  }

  private static void pause() {
    try {
      Thread.sleep(100);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }
  }
}

package si.konferenca.registration.acceptance.support;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.UUID;
import java.util.stream.Stream;
import tools.jackson.databind.JsonNode;

/** The JSON copy directory the backend was started with. */
public final class JsonCopies {

  private final Path directory;

  public JsonCopies(Path directory) {
    this.directory = directory;
  }

  public Path directory() {
    return directory;
  }

  /** Names of the files in the directory (none if it does not exist). */
  public List<String> files() {
    if (!Files.isDirectory(directory)) {
      return List.of();
    }
    try (Stream<Path> files = Files.list(directory)) {
      return files.map(p -> p.getFileName().toString()).sorted().toList();
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  public Path fileOf(UUID id) {
    return directory.resolve(id + ".json");
  }

  public byte[] bytes(UUID id) {
    try {
      return Files.readAllBytes(fileOf(id));
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  public JsonNode json(UUID id) {
    return HttpApi.JSON.readTree(bytes(id));
  }

  public void clear() {
    if (!Files.isDirectory(directory)) {
      return;
    }
    try (Stream<Path> files = Files.list(directory)) {
      for (Path file : files.toList()) {
        Files.deleteIfExists(file);
      }
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }
}

