import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * With HTTPS-only access on, refuses the organizer endpoints over plain HTTP unless the client is
 * local (SR-06, AC-008-04, AC-009-10), before any credential is checked (D-11).
 */
public class HttpsOnlyFilter extends OncePerRequestFilter {

  private final boolean httpsOnly;

  public HttpsOnlyFilter(boolean httpsOnly) {
    this.httpsOnly = httpsOnly;
  }

  @Override
  protected boolean shouldNotFilter(HttpServletRequest request) {
    String path = request.getRequestURI();
    return !httpsOnly || !(path.equals("/api/export") || path.equals("/api/registrations"))
        || !"GET".equals(request.getMethod());
  }

  @Override
  protected void doFilterInternal(
      HttpServletRequest request, HttpServletResponse response, FilterChain chain)
      throws ServletException, IOException {
    if (!ClientAddress.isSecure(request) && !ClientAddress.isLocal(request)) {
      ErrorResponses.write(
          response,
          HttpServletResponse.SC_FORBIDDEN,
          "protocol",
          "Organizer access requires HTTPS.");
      return;
    }
    chain.doFilter(request, response);
  }
}

package si.konferenca.registration.adapter.web;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.time.Clock;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * At most {@code limit} requests per client and endpoint in each clock minute on {@code /api}
 * (SR-03, SB-06); failed organizer logins count too, because this runs before authentication.
 */
public class RateLimitFilter extends OncePerRequestFilter {

  static final long MINUTE_MILLIS = 60_000;
  static final int MAX_TRACKED = 10_000;

  private record Window(long minute, AtomicInteger count) {}

  private final int limit;
  private final Clock clock;
  private final Map<String, Window> windows = new ConcurrentHashMap<>();

  public RateLimitFilter(int limit, Clock clock) {
    this.limit = limit;
    this.clock = clock;
  }

  @Override
  protected boolean shouldNotFilter(HttpServletRequest request) {
    return !request.getRequestURI().startsWith("/api/");
  }

  @Override
  protected void doFilterInternal(
      HttpServletRequest request, HttpServletResponse response, FilterChain chain)
      throws ServletException, IOException {
    long now = clock.millis();
    long minute = now / MINUTE_MILLIS;
    String key =
        ClientAddress.of(request) + ' ' + request.getMethod() + ' ' + request.getRequestURI();
    Window window =
        windows.compute(
            key,
            (k, old) ->
                old == null || old.minute() != minute
                    ? new Window(minute, new AtomicInteger())
                    : old);
    if (windows.size() > MAX_TRACKED) {
      windows.values().removeIf(w -> w.minute() < minute);
    }
    if (window.count().incrementAndGet() > limit) {
      long retryAfter = ((minute + 1) * MINUTE_MILLIS - now + 999) / 1000;
      response.setHeader("Retry-After", String.valueOf(retryAfter));
      ErrorResponses.write(response, 429, "request", "Too many requests. Please try again later.");
      return;
    }
    chain.doFilter(request, response);
  }
}

package si.konferenca.registration.adapter.web;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * Limits request bodies on {@code /api} to {@code maxBytes} (SR-03): a declared larger body is
 * answered 413 at once; an undeclared one fails while it is read and is then answered 413 too.
 */
public class RequestSizeFilter extends OncePerRequestFilter {

  /** Request attribute set when the body exceeded the limit while being read. */
  public static final String TOO_LARGE = RequestSizeFilter.class.getName() + ".tooLarge";

  private final long maxBytes;

  public RequestSizeFilter(long maxBytes) {
    this.maxBytes = maxBytes;
  }

  @Override
  protected boolean shouldNotFilter(HttpServletRequest request) {
    return !request.getRequestURI().startsWith("/api/");
  }

  @Override
  protected void doFilterInternal(
      HttpServletRequest request, HttpServletResponse response, FilterChain chain)
      throws ServletException, IOException {
    if (request.getContentLengthLong() > maxBytes) {
      ErrorResponses.write(response, 413, "body", "The request is too large.");
      return;
    }
    chain.doFilter(new Limited(request, maxBytes), response);
  }

  private static final class Limited extends HttpServletRequestWrapper {

    private final long maxBytes;
    private ServletInputStream stream;

    Limited(HttpServletRequest request, long maxBytes) {
      super(request);
      this.maxBytes = maxBytes;
    }

    @Override
    public ServletInputStream getInputStream() throws IOException {
      if (stream == null) {
        stream = new LimitedStream(super.getInputStream(), maxBytes, this);
      }
      return stream;
    }
  }

  private static final class LimitedStream extends ServletInputStream {

    private final ServletInputStream delegate;
    private final long maxBytes;
    private final HttpServletRequest request;
    private long count;

    LimitedStream(ServletInputStream delegate, long maxBytes, HttpServletRequest request) {
      this.delegate = delegate;
      this.maxBytes = maxBytes;
      this.request = request;
    }

    @Override
    public int read() throws IOException {
      int b = delegate.read();
      if (b >= 0) {
        counted(1);
      }
      return b;
    }

    @Override
    public int read(byte[] buffer, int offset, int length) throws IOException {
      int n = delegate.read(buffer, offset, length);
      if (n > 0) {
        counted(n);
      }
      return n;
    }

    private void counted(int n) throws IOException {
      count += n;
      if (count > maxBytes) {
        request.setAttribute(TOO_LARGE, Boolean.TRUE);
        throw new IOException("request body over the limit");
      }
    }

    @Override
    public boolean isFinished() {
      return delegate.isFinished();
    }

    @Override
    public boolean isReady() {
      return delegate.isReady();
    }

    @Override
    public void setReadListener(ReadListener listener) {
      delegate.setReadListener(listener);
    }
  }
}

package si.konferenca.registration.config;

import java.time.Clock;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import si.konferenca.registration.adapter.web.HttpsOnlyFilter;
import si.konferenca.registration.adapter.web.RateLimitFilter;
import si.konferenca.registration.adapter.web.RequestSizeFilter;

/** Size limit, rate limit and HTTPS-only check, all before Spring Security (order -100). */
@Configuration
public class WebFilterConfiguration {

  @Bean
  FilterRegistrationBean<RequestSizeFilter> requestSizeFilter(AppSettings settings) {
    return registration(new RequestSizeFilter(settings.maxRequestBytes()), -110);
  }

  @Bean
  FilterRegistrationBean<RateLimitFilter> rateLimitFilter(AppSettings settings, Clock clock) {
    return registration(new RateLimitFilter(settings.rateLimitPerMinute(), clock), -105);
  }

  @Bean
  FilterRegistrationBean<HttpsOnlyFilter> httpsOnlyFilter(AppSettings settings) {
    return registration(new HttpsOnlyFilter(settings.organizer().httpsOnly()), -102);
  }

  private static <T extends jakarta.servlet.Filter> FilterRegistrationBean<T> registration(
      T filter, int order) {
    FilterRegistrationBean<T> registration = new FilterRegistrationBean<>(filter);
    registration.setOrder(order);
    return registration;
  }
}

