// The REST API of api-contract.md, used only under /api (AR-01).

export type RegistrationType = "EXTERNAL" | "STUDENT";
export type OptionCategory = "WORKSHOP" | "EVENT" | "MEAL" | "OTHER";

export interface ConferenceOption {
  id: string;
  name: string;
  category: OptionCategory;
  availableTo: RegistrationType[];
}

export interface ConsentDefinition {
  id: string;
  text: string;
  mandatory: boolean;
}

export interface FormConfig {
  options: ConferenceOption[];
  consents: ConsentDefinition[];
  captchaSiteKey: string;
  captchaTestMode?: boolean;
}

export interface RegistrationRequest {
  type: RegistrationType;
  firstName: string;
  lastName: string;
  email: string;
  organization: string | null;
  studyInstitution: string | null;
  studyProgramme: string | null;
  studentId: string | null;
  options: string[];
  consents: string[];
  captchaToken: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export type SubmitResult =
  | { kind: "created"; id: string }
  | { kind: "rejected"; errors: FieldError[] }
  | { kind: "failed" };

export interface SearchItem {
  id: string;
  type: RegistrationType;
  firstName: string;
  lastName: string;
  email: string;
  organization: string | null;
  studyInstitution: string | null;
  options: string[];
  registeredAt: string;
}

export interface SearchResult {
  total: number;
  page: number;
  items: SearchItem[];
}

export interface SearchQuery {
  text: string;
  type: string;
  option: string;
  page: number;
}

export interface Credentials {
  username: string;
  password: string;
}

export type SearchOutcome =
  | { kind: "ok"; result: SearchResult }
  | { kind: "unauthorized" }
  | { kind: "rejected"; errors: FieldError[] }
  | { kind: "failed" };

export const PAGE_SIZE = 20;

export async function fetchFormConfig(): Promise<FormConfig> {
  const response = await fetch("/api/form-config", { headers: { Accept: "application/json" } });
  if (!response.ok) {
    throw new Error("form configuration unavailable");
  }
  return (await response.json()) as FormConfig;
}

async function errorsOf(response: Response): Promise<FieldError[]> {
  try {
    const body = (await response.json()) as { errors?: FieldError[] };
    return Array.isArray(body.errors) ? body.errors : [];
  } catch {
    return [];
  }
}

export async function submitRegistration(request: RegistrationRequest): Promise<SubmitResult> {
  try {
    const response = await fetch("/api/registrations", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify(request),
    });
    if (response.status === 201) {
      const body = (await response.json()) as { id: string };
      return { kind: "created", id: body.id };
    }
    if (response.status === 400) {
      return { kind: "rejected", errors: await errorsOf(response) };
    }
    return { kind: "failed" };
  } catch {
    return { kind: "failed" };
  }
}

/** HTTP Basic value for UTF-8 credentials. */
export function basicAuth({ username, password }: Credentials): string {
  const bytes = new TextEncoder().encode(`${username}:${password}`);
  let binary = "";
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return "Basic " + btoa(binary);
}

export async function searchRegistrations(
  credentials: Credentials,
  query: SearchQuery,
): Promise<SearchOutcome> {
  const params = new URLSearchParams();
  if (query.text.trim() !== "") params.set("text", query.text);
  if (query.type !== "") params.set("type", query.type);
  if (query.option !== "") params.set("option", query.option);
  params.set("page", String(query.page));
  try {
    const response = await fetch(`/api/registrations?${params.toString()}`, {
      headers: {
        Accept: "application/json",
        Authorization: basicAuth(credentials),
        "X-Requested-With": "XMLHttpRequest",
      },
    });
    if (response.status === 200) {
      return { kind: "ok", result: (await response.json()) as SearchResult };
    }
    if (response.status === 401) {
      return { kind: "unauthorized" };
    }
    if (response.status === 400) {
      return { kind: "rejected", errors: await errorsOf(response) };
    }
    return { kind: "failed" };
  } catch {
    return { kind: "failed" };
  }
}

// The fixed participant fields per registration type (BR-01) and the client-side checks
// that mirror the backend rules V-01 … V-03 and the mandatory consents (NFR-03).
import type { ConsentDefinition, RegistrationType } from "../api";

export type FieldName =
  | "firstName"
  | "lastName"
  | "email"
  | "organization"
  | "studyInstitution"
  | "studyProgramme"
  | "studentId";

export interface FieldDefinition {
  name: FieldName;
  label: string;
  inputType: "text" | "email";
}

const COMMON: FieldDefinition[] = [
  { name: "firstName", label: "First name", inputType: "text" },
  { name: "lastName", label: "Last name", inputType: "text" },
  { name: "email", label: "Email", inputType: "email" },
];

export const FIELDS: Record<RegistrationType, FieldDefinition[]> = {
  EXTERNAL: [
    ...COMMON,
    { name: "organization", label: "Organization / institution", inputType: "text" },
  ],
  STUDENT: [
    ...COMMON,
    { name: "studyInstitution", label: "Study institution", inputType: "text" },
    { name: "studyProgramme", label: "Study programme", inputType: "text" },
    { name: "studentId", label: "Student ID", inputType: "text" },
  ],
};

export const MESSAGES = {
  required: "This field is required.",
  email: "Enter a valid email address.",
  consent: "This consent is required.",
};

const EMAIL = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

export type Values = Partial<Record<FieldName, string>>;

/** Field name (or "consents") to message; empty when the form may be sent. */
export function validate(
  type: RegistrationType,
  values: Values,
  givenConsents: string[],
  consents: ConsentDefinition[],
): Record<string, string> {
  const errors: Record<string, string> = {};
  for (const field of FIELDS[type]) {
    const value = (values[field.name] ?? "").trim();
    if (value === "") {
      errors[field.name] = MESSAGES.required;
    } else if (field.name === "email" && !EMAIL.test(value)) {
      errors[field.name] = MESSAGES.email;
    }
  }
  if (consents.some((c) => c.mandatory && !givenConsents.includes(c.id))) {
    errors.consents = MESSAGES.consent;
  }
  return errors;
}

