import { useEffect, useRef } from "react";

// Google reCAPTCHA v2 checkbox, rendered explicitly (docs/02_contracts/recaptcha.md).
interface Grecaptcha {
  render(
    container: HTMLElement,
    parameters: {
      sitekey: string;
      callback: (token: string) => void;
      "expired-callback": () => void;
    },
  ): number;
  reset(widget: number): void;
}

declare global {
  interface Window {
    grecaptcha?: Grecaptcha;
    onRecaptchaLoad?: () => void;
  }
}

export const RECAPTCHA_SCRIPT =
  "https://www.google.com/recaptcha/api.js?render=explicit&onload=onRecaptchaLoad";

let loading: Promise<void> | null = null;

export function loadRecaptcha(): Promise<void> {
  if (window.grecaptcha) {
    return Promise.resolve();
  }
  if (!loading) {
    loading = new Promise((resolve) => {
      window.onRecaptchaLoad = () => resolve();
      const script = document.createElement("script");
      script.src = RECAPTCHA_SCRIPT;
      script.async = true;
      script.defer = true;
      document.head.appendChild(script);
    });
  }
  return loading;
}

interface Props {
  siteKey: string;
  onToken: (token: string) => void;
  /** Increment to reset the widget (after a rejected submission). */
  resetCount: number;
}

export function Recaptcha({ siteKey, onToken, resetCount }: Props) {
  const container = useRef<HTMLDivElement>(null);
  const widget = useRef<number | null>(null);

  useEffect(() => {
    let cancelled = false;
    void loadRecaptcha().then(() => {
      if (cancelled || !container.current || !window.grecaptcha || widget.current !== null) {
        return;
      }
      widget.current = window.grecaptcha.render(container.current, {
        sitekey: siteKey,
        callback: onToken,
        "expired-callback": () => onToken(""),
      });
    });
    return () => {
      cancelled = true;
    };
  }, [siteKey, onToken]);

  useEffect(() => {
    if (resetCount > 0 && widget.current !== null && window.grecaptcha) {
      window.grecaptcha.reset(widget.current);
      onToken("");
    }
  }, [resetCount, onToken]);

  return <div ref={container} data-testid="recaptcha" />;
}

import { type FormEvent, useCallback, useEffect, useState } from "react";
import {
  type ConferenceOption,
  type FormConfig,
  type OptionCategory,
  type RegistrationType,
  fetchFormConfig,
  submitRegistration,
} from "../api";
import { FIELDS, type FieldName, type Values, validate } from "./fields";
import { Recaptcha } from "./Recaptcha";

export const GENERAL_ERROR = "Your registration could not be sent. Please try again later.";
export const TEST_TOKEN = "test-pass";

const GROUPS: { category: OptionCategory; legend: string }[] = [
  { category: "WORKSHOP", legend: "Workshops" },
  { category: "EVENT", legend: "Events" },
  { category: "MEAL", legend: "Meals" },
  { category: "OTHER", legend: "Other activities" },
];

interface Confirmed {
  name: string;
  optionNames: string[];
}

function ErrorText({ id, message }: { id: string; message?: string }) {
  return message ? (
    <span id={id} className="field-error">
      {message}
    </span>
  ) : null;
}

export function RegistrationPage() {
  const [config, setConfig] = useState<FormConfig | null>(null);
  const [loadFailed, setLoadFailed] = useState(false);
  const [type, setType] = useState<RegistrationType | null>(null);
  const [values, setValues] = useState<Values>({});
  const [options, setOptions] = useState<string[]>([]);
  const [consents, setConsents] = useState<string[]>([]);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [generalError, setGeneralError] = useState<string | null>(null);
  const [captchaToken, setCaptchaToken] = useState("");
  const [captchaResets, setCaptchaResets] = useState(0);
  const [submitting, setSubmitting] = useState(false);
  const [confirmed, setConfirmed] = useState<Confirmed | null>(null);

