          value={draft.option}
          onChange={(e) => setDraft({ ...draft, option: e.target.value })}
        >
          <option value="">All options</option>
          {options.map((option) => (
            <option key={option.id} value={option.id}>
              {option.name}
            </option>
          ))}
        </select>
        <button type="submit">Search</button>
      </form>
