package si.konferenca.registration.adapter.captcha;

import static org.assertj.core.api.Assertions.assertThat;

import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class CaptchaVerifierTest {

  private HttpServer server;
  private final AtomicReference<String> received = new AtomicReference<>();

  private RecaptchaVerifier verifierAnswering(int status, String body) throws IOException {
    server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    server.createContext(
        "/verify",
        exchange -> {
          received.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
          byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
          exchange.sendResponseHeaders(status, bytes.length);
          try (OutputStream out = exchange.getResponseBody()) {
            out.write(bytes);
          }
        });
    server.start();
    URI url = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/verify");
    return new RecaptchaVerifier(HttpClient.newHttpClient(), url, "s3cret&key");
  }

  @AfterEach
  void stop() {
    if (server != null) {
      server.stop(0);
    }
  }

  @Test
  void successfulAnswerAcceptsAndSendsEncodedSecretAndToken() throws IOException {
    RecaptchaVerifier verifier = verifierAnswering(200, "{\"success\": true}");

    assertThat(verifier.verify("tok en+1")).isTrue();
    assertThat(received.get()).isEqualTo("secret=s3cret%26key&response=tok+en%2B1");
  }

  @Test
  void failedAnswerRejects() throws IOException {
    assertThat(verifierAnswering(200, "{\"success\": false}").verify("t")).isFalse();
  }

  @Test
  void successThatIsNotABooleanRejects() throws IOException {
    assertThat(verifierAnswering(200, "{\"success\": \"true\"}").verify("t")).isFalse();
  }

  @Test
  void otherStatusRejects() throws IOException {
    assertThat(verifierAnswering(500, "{\"success\": true}").verify("t")).isFalse();
  }

  @Test
  void unparsableAnswerRejects() throws IOException {
    assertThat(verifierAnswering(200, "not json").verify("t")).isFalse();
  }

  @Test
  void unreachableEndpointRejects() {
    RecaptchaVerifier verifier =
        new RecaptchaVerifier(HttpClient.newHttpClient(), URI.create("http://127.0.0.1:1/verify"), "s");

    assertThat(verifier.verify("t")).isFalse();
  }

  @Test
  void interruptedVerificationRejectsAndKeepsTheInterrupt() throws IOException {
    RecaptchaVerifier verifier = verifierAnswering(200, "{\"success\": true}");
    Thread.currentThread().interrupt();
    try {
      assertThat(verifier.verify("t")).isFalse();
      assertThat(Thread.currentThread().isInterrupted()).isTrue();
    } finally {
      Thread.interrupted();
    }
  }

  @Test
  void testModeAcceptsOnlyTheTestToken() {
    TestModeCaptchaVerifier verifier = new TestModeCaptchaVerifier();

    assertThat(verifier.verify("test-pass")).isTrue();
    assertThat(verifier.verify("test-pass ")).isFalse();
    assertThat(verifier.verify("anything")).isFalse();
    assertThat(RecaptchaVerifier.TIMEOUT.toSeconds()).isEqualTo(5);
  }
}

package si.konferenca.registration.adapter.jsoncopy;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import si.konferenca.registration.domain.GivenConsent;
import si.konferenca.registration.domain.Participant;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationType;

class FileJsonCopyStoreTest {

  @TempDir Path temp;

  private static final Instant AT = Instant.parse("2026-10-20T10:15:30.123456Z");

  static Registration registration() {
    return new Registration(
        UUID.fromString("0a1b2c3d-0000-4000-8000-000000000001"),
        new Participant(RegistrationType.STUDENT, "Žan", "Kovač", "zan@uni.si", null, "Uni", "CS", "63"),
        List.of("ws", "meal"),
        List.of(new GivenConsent("privacy", AT)),
        AT);
  }

  @Test
  void writesTheContractDocumentAsCompactUtf8() throws IOException {
    FileJsonCopyStore store = new FileJsonCopyStore(temp.resolve("copies"));

    byte[] written = store.write(registration());

    Path file = temp.resolve("copies/0a1b2c3d-0000-4000-8000-000000000001.json");
    assertThat(Files.readAllBytes(file)).isEqualTo(written);
    assertThat(new String(written, StandardCharsets.UTF_8))
        .isEqualTo(
            "{\"id\":\"0a1b2c3d-0000-4000-8000-000000000001\",\"type\":\"STUDENT\",\"firstName\":\"Žan\","
                + "\"lastName\":\"Kovač\",\"email\":\"zan@uni.si\",\"organization\":null,"
                + "\"studyInstitution\":\"Uni\",\"studyProgramme\":\"CS\",\"studentId\":\"63\","
                + "\"options\":[\"ws\",\"meal\"],\"consents\":[{\"id\":\"privacy\","
                + "\"givenAt\":\"2026-10-20T10:15:30.123456Z\"}],"
                + "\"registeredAt\":\"2026-10-20T10:15:30.123456Z\"}");
    assertThat(Files.list(temp.resolve("copies"))).hasSize(1);
    assertThat(store.directory()).isEqualTo(temp.resolve("copies"));
  }

  @Test
  void writingTwiceReplacesTheCopy() {
    FileJsonCopyStore store = new FileJsonCopyStore(temp);

    store.write(registration());
    store.write(registration());

    assertThat(temp.resolve("0a1b2c3d-0000-4000-8000-000000000001.json")).exists();
  }

  @Test
  void unwritableDirectoryFailsAndLeavesNothing() throws IOException {
    Path blocker = Files.createFile(temp.resolve("blocker"));
    FileJsonCopyStore store = new FileJsonCopyStore(blocker.resolve("copies"));

    assertThatThrownBy(() -> store.write(registration()))
        .isInstanceOf(UncheckedIOException.class)
        .hasMessageContaining("0a1b2c3d-0000-4000-8000-000000000001");
    assertThat(Files.list(temp)).containsExactly(blocker);
  }

  @Test
  void deleteRemovesTheCopyAndToleratesMissingFiles() {
    FileJsonCopyStore store = new FileJsonCopyStore(temp);
    store.write(registration());
    UUID id = registration().id();

    store.delete(id);
    store.delete(id);

    assertThat(temp.resolve(id + ".json")).doesNotExist();
  }

  @Test
  void deleteNeverThrows() throws IOException {
    UUID id = registration().id();
    Path nonEmpty = Files.createDirectories(temp.resolve(id + ".json"));
    Files.createFile(nonEmpty.resolve("keep"));

    new FileJsonCopyStore(temp).delete(id);

    assertThat(nonEmpty).exists();
  }

  @Test
  void healthIsUpOnlyForAWritableDirectory() throws IOException {
    assertThat(new JsonCopyHealthIndicator(temp).health().getStatus().getCode()).isEqualTo("UP");
    Path file = Files.createFile(temp.resolve("file"));
    assertThat(new JsonCopyHealthIndicator(file).health().getStatus().getCode()).isEqualTo("DOWN");
    assertThat(new JsonCopyHealthIndicator(temp.resolve("missing")).health().getStatus().getCode())
        .isEqualTo("DOWN");
  }
}

package si.konferenca.registration.adapter.export;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.time.Instant;
import java.util.List;
import java.util.UUID;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.junit.jupiter.api.Test;
import si.konferenca.registration.domain.GivenConsent;
import si.konferenca.registration.domain.Participant;
import si.konferenca.registration.domain.Registration;
import si.konferenca.registration.domain.RegistrationType;

class PoiWorkbookWriterTest {

  private static final Instant AT = Instant.parse("2026-10-20T10:15:30Z");

  @Test
  void writesHeaderAndOneStringRowPerRegistration() throws IOException {
    Registration external =
        new Registration(
            UUID.fromString("00000000-0000-4000-8000-000000000001"),
            new Participant(RegistrationType.EXTERNAL, "=1+1", "Novak", "a@b.si", "Org", null, null, null),
            List.of("ws", "ev"),
            List.of(new GivenConsent("privacy", AT), new GivenConsent("photos", AT)),
            AT);
    Registration student =
        new Registration(
            UUID.fromString("00000000-0000-4000-8000-000000000002"),
            new Participant(RegistrationType.STUDENT, "Luka", "Šef", "l@u.si", null, "Uni", "CS", "63"),
            List.of(),
            List.of(new GivenConsent("privacy", AT)),
            AT);

    byte[] bytes = new PoiWorkbookWriter().write(List.of(external, student));

    try (XSSFWorkbook workbook = new XSSFWorkbook(new ByteArrayInputStream(bytes))) {
      Sheet sheet = workbook.getSheetAt(0);
      assertThat(sheet.getSheetName()).isEqualTo("registrations");
      assertThat(sheet.getLastRowNum()).isEqualTo(2);
      assertThat(values(sheet.getRow(0))).isEqualTo(PoiWorkbookWriter.COLUMNS);
      Row first = sheet.getRow(1);
      assertThat(values(first))
          .containsExactly(
              "00000000-0000-4000-8000-000000000001", "EXTERNAL", "=1+1", "Novak", "a@b.si", "Org",
              "", "", "", "ws, ev", "privacy, photos", "2026-10-20T10:15:30Z");
      assertThat(first.getCell(2).getCellType()).as("never a formula").isEqualTo(CellType.STRING);
      assertThat(first.getCell(6)).isNull();
      assertThat(values(sheet.getRow(2)))
          .containsExactly(
              "00000000-0000-4000-8000-000000000002", "STUDENT", "Luka", "Šef", "l@u.si", "", "Uni",
              "CS", "63", "", "privacy", "2026-10-20T10:15:30Z");
    }
  }

  @Test
  void emptyExportHasOnlyTheHeader() throws IOException {
    try (XSSFWorkbook workbook =
        new XSSFWorkbook(new ByteArrayInputStream(new PoiWorkbookWriter().write(List.of())))) {
      assertThat(workbook.getSheetAt(0).getLastRowNum()).isZero();
      assertThat(workbook.getNumberOfSheets()).isEqualTo(1);
    }
  }

  private static List<String> values(Row row) {
    return java.util.stream.IntStream.range(0, PoiWorkbookWriter.COLUMNS.size())
        .mapToObj(i -> row.getCell(i) == null ? "" : row.getCell(i).getStringCellValue())
        .toList();
  }
}

