import { act, render } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Recaptcha } from "./Recaptcha";

type Parameters = {
  sitekey: string;
  callback: (token: string) => void;
  "expired-callback": () => void;
};

function fakeGrecaptcha() {
  const rendered: Parameters[] = [];
  const grecaptcha = {
    render: vi.fn((_container: HTMLElement, parameters: Parameters) => {
      rendered.push(parameters);
      return 7;
    }),
    reset: vi.fn(),
  };
  window.grecaptcha = grecaptcha;
  return { grecaptcha, rendered };
}

beforeEach(() => {
  delete window.grecaptcha;
});

afterEach(() => {
  delete window.grecaptcha;
});

describe("Recaptcha widget", () => {
  it("renders the widget with the site key and passes tokens on", async () => {
    const { grecaptcha, rendered } = fakeGrecaptcha();
    const onToken = vi.fn();

    render(<Recaptcha siteKey="site-key" onToken={onToken} resetCount={0} />);
    await vi.waitFor(() => expect(grecaptcha.render).toHaveBeenCalledTimes(1));

    expect(rendered[0].sitekey).toBe("site-key");
    rendered[0].callback("token-1");
    expect(onToken).toHaveBeenLastCalledWith("token-1");
    rendered[0]["expired-callback"]();
    expect(onToken).toHaveBeenLastCalledWith("");
    expect(grecaptcha.reset).not.toHaveBeenCalled();
  });

  it("resets the widget and clears the token when asked", async () => {
    const { grecaptcha } = fakeGrecaptcha();
    const onToken = vi.fn();
    const { rerender } = render(<Recaptcha siteKey="k" onToken={onToken} resetCount={0} />);
    await vi.waitFor(() => expect(grecaptcha.render).toHaveBeenCalled());

    rerender(<Recaptcha siteKey="k" onToken={onToken} resetCount={1} />);

    expect(grecaptcha.reset).toHaveBeenCalledWith(7);
    expect(onToken).toHaveBeenCalledWith("");
  });

  it("does not render after it was removed", async () => {
    const { grecaptcha } = fakeGrecaptcha();
    const { unmount } = render(<Recaptcha siteKey="k" onToken={vi.fn()} resetCount={0} />);
    unmount();
    await act(async () => {
      await Promise.resolve();
    });

    expect(grecaptcha.render).not.toHaveBeenCalled();
  });

  it("does not reset before the widget exists", () => {
    const onToken = vi.fn();
    render(<Recaptcha siteKey="k" onToken={onToken} resetCount={1} />);

    expect(onToken).not.toHaveBeenCalled();
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";

afterEach(() => {
  delete window.grecaptcha;
  delete window.onRecaptchaLoad;
  document.head.querySelectorAll("script").forEach((s) => s.remove());
  vi.resetModules();
});

describe("reCAPTCHA loader", () => {
  it("resolves at once when the script is already there", async () => {
    window.grecaptcha = { render: vi.fn(), reset: vi.fn() };
    const { loadRecaptcha } = await import("./recaptchaLoader");

    await expect(loadRecaptcha()).resolves.toBeUndefined();
    expect(document.head.querySelector("script")).toBeNull();
  });

  it("adds the script once and resolves when Google calls back", async () => {
    const { loadRecaptcha, RECAPTCHA_SCRIPT } = await import("./recaptchaLoader");

    const first = loadRecaptcha();
    const second = loadRecaptcha();
    const scripts = document.head.querySelectorAll("script");

    expect(second).toBe(first);
    expect(scripts).toHaveLength(1);
    expect(scripts[0].src).toBe(RECAPTCHA_SCRIPT);
    expect(scripts[0].async).toBe(true);
    expect(scripts[0].defer).toBe(true);
    expect(RECAPTCHA_SCRIPT).toContain("render=explicit");
    window.onRecaptchaLoad?.();
    await expect(first).resolves.toBeUndefined();
  });
});

import { fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import type { FormConfig } from "../api";
import { GENERAL_ERROR, RegistrationPage } from "./RegistrationPage";

const config: FormConfig = {
  options: [
    { id: "ws", name: "Workshop", category: "WORKSHOP", availableTo: ["EXTERNAL", "STUDENT"] },
    { id: "ex", name: "Dinner", category: "EVENT", availableTo: ["EXTERNAL"] },
  ],
  consents: [{ id: "privacy", text: "I agree.", mandatory: true }],
  captchaSiteKey: "site-key",
  captchaTestMode: false,
};

let rendered: { callback: (token: string) => void } | null = null;

function backend(post: (body: Record<string, unknown>) => Response, formConfig = config) {
  const posts: Record<string, unknown>[] = [];
  window.grecaptcha = {
    render: vi.fn((_c: HTMLElement, parameters: { callback: (t: string) => void }) => {
      rendered = parameters;
      return 1;
    }),
    reset: vi.fn(),
  };
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: string, init?: RequestInit) => {
      if (url === "/api/form-config") return Response.json(formConfig);
      const body = JSON.parse(String(init?.body)) as Record<string, unknown>;
      posts.push(body);
      return post(body);
    }),
  );
  return posts;
}

function fill() {
  fireEvent.change(screen.getByLabelText("First name"), { target: { value: " Ana " } });
  fireEvent.change(screen.getByLabelText("Last name"), { target: { value: "Novak" } });
  fireEvent.change(screen.getByLabelText("Email"), { target: { value: "ana@example.org" } });
  fireEvent.change(screen.getByLabelText("Organization / institution"), {
    target: { value: "Org" },
  });
  fireEvent.click(screen.getByRole("checkbox", { name: /I agree/ }));
}

afterEach(() => {
  vi.unstubAllGlobals();
  delete window.grecaptcha;
  rendered = null;
});

