import sys

root = sys.argv[1]


def append_tests(path, block):
    with open(path, encoding="utf-8") as f:
        s = f.read().rstrip()
    assert s.endswith("});"), path
    s = s[:-3] + block + "});\n"
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(s)


def replace(path, old, new):
    with open(path, encoding="utf-8") as f:
        s = f.read()
    assert old in s, (path, old)
    s = s.replace(old, new, 1)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(s)


